<template><dialog ref="dialog" id="agione-request-dialog" data-agione-dialog-id="agione-request-dialog" @close="afterClose" @pointerdown="backdrop.onPointerDown" @click="backdrop.onClick" @pointercancel="backdrop.reset" class="requests-dialog" :class="{'request-drawer':!!state.drawer?.groupMeta}" aria-labelledby="requestDrawerTitle" @cancel.prevent="$emit('close')"><div class="dialog-head"><h2 id="requestDrawerTitle">{{ t(state.evidence ? 'agione.requestDetails' : state.drawer?.groupMeta ? 'agione.groupDetails' : 'agione.requestLog') }}</h2><button :title="t('agione.closeDialog')" :aria-label="t('agione.closeDialog')" @click="$emit('close')">×</button></div><div id="agione-request-dialog-body" data-agione-dialog-body><div v-if="state.evidence" class="request-content"><button data-return-requests @click="$emit('back')">← {{ t('agione.backRequests') }}</button><div class="evidence-identity"><h3>{{ record.customerName || record.customerId || record.customerTenantId || t('agione.customerMissing') }}</h3><p>{{ time(record.occurredAt || record.occurred_at) }} · {{ t('agione.timezoneLabel') }}</p><small>{{ t('agione.requestId') }} {{ record.recordId || record.record_id }}</small></div><div class="evidence-facts"><div><small>{{ t('agione.modelLabel') }}</small><strong>{{ record.modelId || record.model_id || t('agione.unassigned') }}</strong></div><div><small>{{ t('agione.resultReason') }}</small><strong>{{ result(record.result || record.status) }}{{ failure(record) ? ' · '+failure(record) : '' }}</strong></div><div><small>{{ t('agione.inputOutputTokens') }}</small><strong>{{ fmt(record.inputTokens ?? record.input_tokens) }} / {{ fmt(record.outputTokens ?? record.output_tokens) }}</strong></div><div><small>{{ t('agione.billingLink') }}</small><strong>{{ t('agione.' + ({LINKED:'linked',NOT_LINKED:'notLinked',UNAVAILABLE:'unavailable'}[record.financialLinkState] || 'unknown')) }}</strong><button class="link" disabled :title="t('agione.billingUnavailableHelp')">{{ t('agione.viewBillingDetails') }}</button><small role="status">{{ t('agione.technicalProjection') }}</small></div></div><details class="request-raw"><summary>{{ t('agione.technicalFields') }}</summary><p>{{ t('agione.technicalFieldsHelp') }}</p><pre>{{ JSON.stringify(evidence,null,2) }}</pre></details></div><template v-else><div class="request-content"><div style="display:contents" @click="copyIdentity" v-html="groupHeader"></div><span v-if="copyStatus" class="drawer-copy-status" role="status" aria-live="polite">{{ copyStatus }}</span><div v-if="state.drawerLoading" class="loading">{{ t('agione.requestsLoading') }}</div><p v-else-if="state.drawerError" role="alert">{{ t('agione.errors.networkError') }}<button @click="$emit('page',state.drawer?.page||1)">{{ t('agione.retryPage') }}</button></p><template v-else><div class="request-meta"><strong>{{ t('agione.requestCountLabel',{count:fmt(state.drawer?.total)}) }}</strong><span>{{ t('agione.requestScopeHint') }}</span><details><summary>{{ t('agione.dataDetails') }}</summary><p>{{ t('agione.requestDataHelp') }}</p><small>{{ t(state.isLive ? 'agione.live.originalAsOf' : 'agione.dataVersion') }} {{ state.isLive ? time(state.provenance?.fetchedAt) : state.dataVersion }}</small></details></div><div style="display:contents" @click="rowsClick" v-html="rowsHtml"></div></template></div><div v-if="!state.drawerLoading&&!state.drawerError" class="request-footer"><div class="pager"><button :disabled="(state.drawer?.page||1)<=1" @click="$emit('page',state.drawer.page-1)">{{ t('agione.previousPage') }}</button><span>{{ t('agione.requestPagination',{page:state.drawer?.page||1,pages:Math.max(1,Math.ceil((state.drawer?.total||0)/20)),total:fmt(state.drawer?.total)}) }}</span><button :disabled="(state.drawer?.page||1)*20 >= (state.drawer?.total||0)" @click="$emit('page',state.drawer.page+1)">{{ t('agione.nextPage') }}</button></div></div></template></div></dialog></template>
<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import DOMPurify from 'dompurify'
import { claimOriginalDialog, createDialogBackdropDismiss, releaseOriginalDialog } from '@/utils/agioneDialog'
import { originalWorkspaceState } from '@/utils/agioneOriginalWorkspace'
import { renderOriginalWorkspace } from './original-workspace-renderers.mjs'
const { t, locale }=useI18n({useScope:'global'})
const props=defineProps({state:{type:Object,required:true}})
const emit=defineEmits(['close','page','evidence','back'])
const dialog=ref(null)
const copyStatus=ref('')
async function copyIdentity(event){
  const button=event.target.closest('[data-copy-id]')
  if(!button)return
  try {
    await navigator.clipboard.writeText(button.dataset.copyId)
    copyStatus.value=locale.value.startsWith('zh')?'复制成功':'Copied'
  } catch {
    copyStatus.value=locale.value.startsWith('zh')?'复制失败，请手动选择复制':'Copy failed; select the ID to copy it'
  }
}
const backdrop=createDialogBackdropDismiss(()=>emit('close'))
watch(()=>!!props.state.drawer,async open=>{await nextTick();if(!dialog.value)return;if(open&&!dialog.value.open){claimOriginalDialog(dialog.value);dialog.value.showModal()}else if(!open&&dialog.value.open){dialog.value.close();releaseOriginalDialog(dialog.value)}},{immediate:true})
onBeforeUnmount(()=>{backdrop.reset();releaseOriginalDialog(dialog.value,{force:true})})
function afterClose(){if(dialog.value?.open)return;backdrop.reset();releaseOriginalDialog(dialog.value);if(props.state.drawer)emit('close')}
const groupHeader=computed(()=>{const d=props.state.drawer;if(!d?.groupMeta)return '';const [tenant,user]=String(d.groupKey?.userId||'').split(':');const row=(d.items||[]).find(x=>String(x.customer_id||x.customerId||x.customerTenantId||'')===tenant&&String(x.user_id||x.userId||'')===user);return DOMPurify.sanitize(renderOriginalWorkspace(originalWorkspaceState(props.state),'groupHeader',{locale:locale.value,drawer:true,body:{window:props.state.window,groupKey:d.groupKey},groupLabel:d.groupMeta.label,callerName:row?.userName,customerName:row?.customerName,groupSummary:d.groupMeta.summary}))})
const failureLabel=key=>{const mapped={BALANCE_INSUFFICIENT:'insufficientBalance',INSUFFICIENT_BALANCE:'insufficientBalance',TECHNICAL:'technicalFailure',UNMAPPED:'unmappedReason',UNKNOWN:'unknownReason','余额不足':'insufficientBalance','技术失败':'technicalFailure'}[key];return mapped?t('agione.'+mapped):key||t('agione.unknownReason')}
const failure=row=>(row.result || row.status)==='SUCCESS'?'':failureLabel(row.failureKey || row.failureType || row.failure_type)
const rowsHtml=computed(()=>{const items=(props.state.drawer?.items||[]).map(row=>({record_id:row.recordId||row.record_id,customerName:row.customerName||row.customerId||row.customer_id||row.customerTenantId,occurred_at:row.occurredAt||row.occurred_at,model_id:row.modelId||row.model_id,user_id:row.userId||row.user_id,result:row.result||row.status,input_tokens:row.inputTokens??row.input_tokens,output_tokens:row.outputTokens??row.output_tokens,raw:{failureTypeName:failure(row),userName:row.userName,modelName:row.modelName}}));return DOMPurify.sanitize(renderOriginalWorkspace(originalWorkspaceState(props.state),'requestRows',{items,locale:locale.value}))})
function rowsClick(event){const button=event.target.closest('[data-record]');if(!button)return;const row=props.state.drawer.items[Number(button.dataset.record)];if(row)emit('evidence',String(row.evidenceId||row.recordId||row.record_id))}
const record=computed(()=>props.state.evidence?.record||props.state.evidence?.evidence||props.state.evidence||{})
const evidence=computed(()=>{const allowed=['recordId','record_id','customerId','customer_id','customerTenantId','occurredAt','occurred_at','modelId','model_id','result','status','failureKey','failureType','failure_type','inputTokens','input_tokens','outputTokens','output_tokens','duration','latencyState','financialLinkState'];return Object.fromEntries(Object.entries(record.value).filter(([key])=>allowed.includes(key)))})
const fmt=value=>typeof value==='number'?new Intl.NumberFormat(locale.value.startsWith('zh')?'zh-CN':'en-GB').format(value):'—'
const result=value=>t('agione.'+({SUCCESS:'success',FAILURE:'failure',UNKNOWN:'unknown'}[value]||'unknown'))
const time=value=>value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString(locale.value.startsWith('zh')?'zh-CN':'en-GB',{timeZone:'Asia/Shanghai'}):t('agione.timeMissing')
</script>
